CREATE OR REPLACE FUNCTION public.event_module_access(_uid uuid,_event uuid,_level text DEFAULT 'view') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.events e WHERE e.id=_event AND public.has_company_access(_uid,e.company_id,'resource_plan',_level)) $$;
CREATE OR REPLACE FUNCTION public.event_technician_company_access(_auth_user_id uuid,_event_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.event_module_access(_auth_user_id,_event_id,'view') $$;
CREATE OR REPLACE FUNCTION public.person_module_access(_uid uuid,_person uuid,_level text DEFAULT 'view') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_super_admin(_uid) OR EXISTS(SELECT 1 FROM public.employment_profiles e WHERE e.person_id=_person AND e.archived_at IS NULL AND public.has_company_access(_uid,e.company_id,'employees',_level)) $$;
CREATE OR REPLACE FUNCTION public.technician_module_access(_uid uuid,_technician_user uuid,_level text DEFAULT 'view') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_accounts a JOIN public.employment_profiles ep ON ep.person_id=a.person_id WHERE a.auth_user_id=_technician_user AND a.is_active AND ep.archived_at IS NULL AND public.has_company_access(_uid,ep.company_id,'resource_plan',_level)) $$;
GRANT EXECUTE ON FUNCTION public.event_module_access(uuid,uuid,text),public.person_module_access(uuid,uuid,text),public.technician_module_access(uuid,uuid,text) TO authenticated,service_role;
DO $$ DECLARE r record; m text; lvl text; cmd text; BEGIN
 FOR r IN SELECT t.table_name FROM information_schema.tables t JOIN information_schema.columns c ON c.table_schema=t.table_schema AND c.table_name=t.table_name AND c.column_name='company_id' WHERE t.table_schema='public' AND t.table_type='BASE TABLE' AND (t.table_name LIKE 'hms_%' OR t.table_name LIKE 'compliance_%' OR t.table_name IN ('events','schedule_blocks','employment_profiles','employee_work_profiles','customers','customer_contact_tags','calculations','offers','invoice_basis','calc_cases','calc_ai_drafts')) LOOP
 m:= CASE WHEN r.table_name IN ('events','schedule_blocks') THEN 'resource_plan' WHEN r.table_name IN ('employment_profiles') THEN 'employees' WHEN r.table_name IN ('compliance_org_roles','compliance_role_templates','compliance_responsibility_types') THEN 'organisation' WHEN r.table_name IN ('customers','customer_contact_tags') THEN 'customers' WHEN r.table_name IN ('calculations','offers','invoice_basis','calc_cases','calc_ai_drafts') THEN 'finance' ELSE 'hms' END;
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',r.table_name);
 EXECUTE format('CREATE POLICY phase2_module_view ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING (public.has_company_access(auth.uid(),company_id,%L,''view''))',r.table_name,m);
 EXECUTE format('CREATE POLICY phase2_module_insert ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.has_company_access(auth.uid(),company_id,%L,''edit''))',r.table_name,m);
 EXECUTE format('CREATE POLICY phase2_module_update ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.has_company_access(auth.uid(),company_id,%L,''edit'')) WITH CHECK (public.has_company_access(auth.uid(),company_id,%L,''edit''))',r.table_name,m,m);
 EXECUTE format('CREATE POLICY phase2_module_delete ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING (public.has_company_access(auth.uid(),company_id,%L,''admin''))',r.table_name,m);
 END LOOP;
END $$;
CREATE POLICY phase2_resource_view ON public.events FOR SELECT TO authenticated USING(public.has_company_access(auth.uid(),company_id,'resource_plan','view'));
CREATE POLICY phase2_resource_insert ON public.events FOR INSERT TO authenticated WITH CHECK(public.has_company_access(auth.uid(),company_id,'resource_plan','edit'));
CREATE POLICY phase2_resource_update ON public.events FOR UPDATE TO authenticated USING(public.has_company_access(auth.uid(),company_id,'resource_plan','edit')) WITH CHECK(public.has_company_access(auth.uid(),company_id,'resource_plan','edit'));
CREATE POLICY phase2_resource_blocks ON public.schedule_blocks FOR ALL TO authenticated USING(public.has_company_access(auth.uid(),company_id,'resource_plan','view')) WITH CHECK(public.has_company_access(auth.uid(),company_id,'resource_plan','edit'));
CREATE POLICY phase2_assignments_view ON public.event_technicians AS RESTRICTIVE FOR SELECT TO authenticated USING(public.event_module_access(auth.uid(),event_id,'view'));
CREATE POLICY phase2_assignments_insert ON public.event_technicians AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.event_module_access(auth.uid(),event_id,'edit'));
CREATE POLICY phase2_assignments_update ON public.event_technicians AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.event_module_access(auth.uid(),event_id,'edit')) WITH CHECK(public.event_module_access(auth.uid(),event_id,'edit'));
CREATE POLICY phase2_assignments_delete ON public.event_technicians AS RESTRICTIVE FOR DELETE TO authenticated USING(public.event_module_access(auth.uid(),event_id,'edit'));
CREATE POLICY phase2_assignments_manage ON public.event_technicians FOR ALL TO authenticated USING(public.event_module_access(auth.uid(),event_id,'view')) WITH CHECK(public.event_module_access(auth.uid(),event_id,'edit'));
CREATE POLICY phase2_people_view ON public.people AS RESTRICTIVE FOR SELECT TO authenticated USING(public.person_module_access(auth.uid(),id,'view') OR EXISTS(SELECT 1 FROM public.user_accounts a WHERE a.person_id=people.id AND a.auth_user_id=auth.uid()));
CREATE POLICY phase2_people_write ON public.people AS RESTRICTIVE FOR ALL TO authenticated USING(public.person_module_access(auth.uid(),id,'view')) WITH CHECK(public.person_module_access(auth.uid(),id,'edit'));
CREATE POLICY phase2_accounts_view ON public.user_accounts AS RESTRICTIVE FOR SELECT TO authenticated USING(auth_user_id=auth.uid() OR public.person_module_access(auth.uid(),person_id,'view'));
CREATE POLICY phase2_accounts_write ON public.user_accounts AS RESTRICTIVE FOR ALL TO authenticated USING(auth_user_id=auth.uid() OR public.person_module_access(auth.uid(),person_id,'view')) WITH CHECK(public.person_module_access(auth.uid(),person_id,'edit'));
CREATE POLICY phase2_technician_view ON public.technicians AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.technician_module_access(auth.uid(),user_id,'view') OR public.is_super_admin(auth.uid()));
CREATE POLICY phase2_technician_resource ON public.technicians FOR SELECT TO authenticated USING(public.technician_module_access(auth.uid(),user_id,'view'));
REVOKE SELECT ON public.technicians FROM authenticated;
GRANT SELECT(id,user_id,microsoft_user_id,name,email,created_at,color,is_plannable_resource,archived_at,archived_by,avatar_id,deleted_at,deleted_by) ON public.technicians TO authenticated;
COMMENT ON FUNCTION public.resource_plan_personnel(uuid[]) IS 'Restricted resource roster; deliberately omits email, date of birth, certificates, notes and other HR fields.';